    @Test
    void revise_keepsHistoryAndValidatesNeighbors() throws Exception {
        register("eq-rev", 1000);
        addReading("eq-rev", "rv1", 1, "r1", "2026-01-01T10:00:00Z", 100, 201);
        addReading("eq-rev", "rv2", 2, "r2", "2026-01-01T11:00:00Z", 200, 201);

