   - idempotency: "REVISE_TEMPLATE", fingerprint templateId|items canonical
   - newVersion = current+1; insert items; update head
   - return TemplateResponse

3. getTemplate(templateId) readOnly → current version + items; 404
4. listTemplateVersions(templateId) readOnly → all versions; 404 if head missing

5. registerMaterial(RegisterMaterialRequest req) @Transactional
