                .sorted()
                .collect(Collectors.joining(","));
    }

    private String canonicalMaterials(List<MaterialSummaryInput> materials) {
        return materials.stream()
                .map(m -> m.batchCode() + ":" + m.quantity() + ":" + m.unit() + ":" + m.summary())
                .sorted()
                .collect(Collectors.joining(","));
