37	    /**
38	     * 计算设备当前周期的证据诊断。调用方应已取得设备行锁（写路径）；查询路径只读调用。
39	     */
40	    public EvidenceDiagnostics diagnose(Equipment equipment) {
41	        String equipmentId = equipment.equipmentId();
42	        long cycleNo = equipment.currentCycleNo();
43	
44	        Optional<Reading> latest = equipmentRepository.findLatestReading(equipmentId);
45	        Optional<MaintenanceRecord> last = equipmentRepository.findLastMaintenance(equipmentId);
46	        long latestCumulative = latest.map(Reading::cumulativeMinutes).orElse(0L);
47	        long anchorCumulative = last.map(MaintenanceRecord::anchorCumulativeMinutes).orElse(0L);
48	        long runMinutes = latestCumulative - anchorCumulative;
49	        boolean overdue = runMinutes >= equipment.maintenancePeriodMinutes() * 2;
50	
51	        String templateId = equipment.templateId();
52	        if (templateId == null) {
53	            // 未分配模板的设备不启用证据包门禁：无证据包也视为"无缺失"，由调用方决定流程。
54	            return new EvidenceDiagnostics(null, null, runMinutes, overdue, 0, 0,
55	                    List.of(), List.of(), List.of(), 0);
56	        }
57	
58	        Integer currentTemplateVersion = evidenceRepository.findTemplateCurrentVersion(templateId).orElse(null);
